-- ICT371 Question 5: Hostel Room Allocation (MySQL 8.0)
CREATE DATABASE IF NOT EXISTS ict371_q05_hostel; USE ict371_q05_hostel;
CREATE TABLE Students(student_id INT AUTO_INCREMENT PRIMARY KEY,student_number VARCHAR(30) NOT NULL UNIQUE,full_name VARCHAR(120) NOT NULL);
CREATE TABLE Rooms(room_id INT AUTO_INCREMENT PRIMARY KEY,room_number VARCHAR(20) NOT NULL UNIQUE,capacity INT NOT NULL CHECK(capacity>0));
CREATE TABLE Allocations(allocation_id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,room_id INT NOT NULL,allocated_on DATE NOT NULL,released_on DATE NULL,status ENUM('ACTIVE','ENDED') NOT NULL,FOREIGN KEY(student_id) REFERENCES Students(student_id),FOREIGN KEY(room_id) REFERENCES Rooms(room_id),CHECK((status='ACTIVE' AND released_on IS NULL) OR (status='ENDED' AND released_on IS NOT NULL)));
CREATE TABLE occupancy_snapshot(snapshot_date DATE NOT NULL,room_id INT NOT NULL,occupied_beds INT NOT NULL,free_beds INT NOT NULL,PRIMARY KEY(snapshot_date,room_id),FOREIGN KEY(room_id) REFERENCES Rooms(room_id));
INSERT INTO Students(student_number,full_name) VALUES('H001','Luka'),('H002','Misozi'),('H003','Tawanda'),('H004','Chisomo'); INSERT INTO Rooms(room_number,capacity) VALUES('A1',2),('A2',3),('B1',1);
INSERT INTO Allocations(student_id,room_id,allocated_on,released_on,status) VALUES(1,1,CURRENT_DATE,NULL,'ACTIVE'),(2,1,CURRENT_DATE,NULL,'ACTIVE'),(3,2,CURRENT_DATE,NULL,'ACTIVE'),(4,2,CURRENT_DATE-INTERVAL 20 DAY,CURRENT_DATE-INTERVAL 1 DAY,'ENDED');
DELIMITER $$
CREATE FUNCTION fn_free_beds(p_room_id INT) RETURNS INT DETERMINISTIC READS SQL DATA BEGIN DECLARE v_capacity INT; DECLARE v_used INT; SELECT capacity INTO v_capacity FROM Rooms WHERE room_id=p_room_id; IF v_capacity IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown room'; END IF; SELECT COUNT(*) INTO v_used FROM Allocations WHERE room_id=p_room_id AND status='ACTIVE'; RETURN v_capacity-v_used; END$$
CREATE TRIGGER trg_allocation_guard BEFORE INSERT ON Allocations FOR EACH ROW BEGIN DECLARE v_capacity INT; DECLARE v_used INT; IF NEW.status='ACTIVE' THEN SELECT capacity INTO v_capacity FROM Rooms WHERE room_id=NEW.room_id; IF v_capacity IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown room'; END IF; SELECT COUNT(*) INTO v_used FROM Allocations WHERE room_id=NEW.room_id AND status='ACTIVE'; IF v_used>=v_capacity THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Room is full'; END IF; IF EXISTS(SELECT 1 FROM Allocations WHERE student_id=NEW.student_id AND status='ACTIVE') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Student already has active allocation'; END IF; END IF; END$$
CREATE TRIGGER trg_allocation_guard_update BEFORE UPDATE ON Allocations FOR EACH ROW BEGIN DECLARE v_capacity INT; DECLARE v_used INT; IF NEW.status='ACTIVE' THEN SELECT capacity INTO v_capacity FROM Rooms WHERE room_id=NEW.room_id; IF v_capacity IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown room'; END IF; SELECT COUNT(*) INTO v_used FROM Allocations WHERE room_id=NEW.room_id AND status='ACTIVE' AND allocation_id<>OLD.allocation_id; IF v_used>=v_capacity THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Room is full'; END IF; IF EXISTS(SELECT 1 FROM Allocations WHERE student_id=NEW.student_id AND status='ACTIVE' AND allocation_id<>OLD.allocation_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Student already has active allocation'; END IF; END IF; END$$
CREATE PROCEDURE pr_allocate_room(IN p_student_id INT,IN p_room_id INT,IN p_allocated_on DATE) BEGIN IF NOT EXISTS(SELECT 1 FROM Students WHERE student_id=p_student_id) OR NOT EXISTS(SELECT 1 FROM Rooms WHERE room_id=p_room_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown student or room'; END IF; IF EXISTS(SELECT 1 FROM Allocations WHERE student_id=p_student_id AND status='ACTIVE') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Student already has active allocation'; END IF; IF fn_free_beds(p_room_id)<=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='No room capacity'; END IF; INSERT INTO Allocations(student_id,room_id,allocated_on,released_on,status) VALUES(p_student_id,p_room_id,p_allocated_on,NULL,'ACTIVE'); END$$
CREATE PROCEDURE pr_refresh_occupancy() BEGIN INSERT INTO occupancy_snapshot(snapshot_date,room_id,occupied_beds,free_beds) SELECT CURRENT_DATE,r.room_id,COUNT(a.allocation_id),r.capacity-COUNT(a.allocation_id) FROM Rooms r LEFT JOIN Allocations a ON a.room_id=r.room_id AND a.status='ACTIVE' GROUP BY r.room_id,r.capacity ON DUPLICATE KEY UPDATE occupied_beds=VALUES(occupied_beds),free_beds=VALUES(free_beds); END$$
DELIMITER ;
CREATE VIEW v_room_occupancy AS SELECT r.room_id,r.room_number,r.capacity,COUNT(a.allocation_id) occupied_beds,r.capacity-COUNT(a.allocation_id) free_beds FROM Rooms r LEFT JOIN Allocations a ON a.room_id=r.room_id AND a.status='ACTIVE' GROUP BY r.room_id,r.room_number,r.capacity;
CREATE INDEX ix_allocations_room_status ON Allocations(room_id,status);
EXPLAIN SELECT allocation_id,student_id,allocated_on FROM Allocations WHERE room_id=1 AND status='ACTIVE';
SET GLOBAL event_scheduler=ON; CREATE EVENT IF NOT EXISTS ev_refresh_occupancy ON SCHEDULE EVERY 1 DAY STARTS (TIMESTAMP(CURRENT_DATE+INTERVAL 1 DAY,'23:55:00')) DO CALL pr_refresh_occupancy();
